import express from 'express';
import { context, propagation, trace, SpanKind } from '@opentelemetry/api';
import fetch from 'node-fetch';

const app = express();
const tracer = trace.getTracer('inventory-gateway');

app.get('/inventory/:sku', async (req, res) => {
  const parentContext = propagation.extract(context.active(), req.headers);
  const span = tracer.startSpan('inventory.lookup', { kind: SpanKind.SERVER }, parentContext);
  const requestContext = trace.setSpan(parentContext, span);
  try {
    const headers = {};
    propagation.inject(requestContext, headers);
    const upstream = await fetch(`http://inventory/internal/items/${req.params.sku}`, { headers });
    res.status(upstream.status).send(await upstream.text());
  } catch (error) {
    span.recordException(error);
    res.status(502).send('upstream failure');
  } finally {
    span.end();
  }
});

app.listen(3000);
